import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Pure value of each candidate, scaled by the max candidate value to [0, 1]."""
    vmax = values.max() if values.size > 0 else 0.0
    return values / (vmax + 1e-9)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Centred, max-abs-scaled value-minus-weight surplus of each candidate, clipped to [-1, 1]."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    d = v - w
    if d.size == 0:
        return d
    d = d - d.mean()
    denom = np.max(np.abs(d))
    if denom < 1e-12:
        return np.zeros_like(d)
    return np.clip(d / denom, -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Tail-gated exact-fit: g * (1 - |remaining - weight| / max(remaining,1)), g = clip(1 - remaining/(0.08*capacity), 0, 1)."""
    denom = 0.08 * capacity
    if denom <= 0:
        g = np.zeros_like(weights, dtype=float)
    else:
        g = np.clip(1.0 - remaining / denom, 0.0, 1.0)
    closeness = 1.0 - np.abs(remaining - weights) / max(remaining, 1)
    return g * closeness

