import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Gated (30% of capacity) difference between exact residual subset-sum fill after taking each candidate and its normalised density."""
    k = len(values)
    if k == 0 or remaining <= 1:
        return np.zeros(k)

    g = 1.0 - remaining / (0.30 * capacity)
    g = min(max(g, 0.0), 1.0)
    if g <= 0.0:
        return np.zeros(k)

    w = np.maximum(weights.astype(np.int64), 1)
    eff = values.astype(np.float64) / w.astype(np.float64)
    eff_n = eff / max(float(eff.max()), 1e-9)

    f = np.zeros(k)
    for i in range(k):
        r_i = int(remaining) - int(weights[i])
        if r_i <= 0:
            f[i] = 0.0
            continue
        b = 1
        for j in range(k):
            if j == i:
                continue
            b |= b << int(weights[j])
        mask = (1 << (r_i + 1)) - 1
        best = (b & mask).bit_length() - 1
        f[i] = best / max(r_i, 1)

    score = g * (f - eff_n)
    return np.clip(score, -1.0, 1.0)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Leave-one-out exact marginal loss: for each candidate, the drop in best achievable pool value when that candidate is removed from the pool, normalised by total pool value, gated to rem <= 12% of capacity."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=np.int64)
    k = w.size
    rem = int(remaining)
    cap = max(float(capacity), 1.0)
    if k == 0 or rem <= 1 or rem > 0.12 * cap:
        return np.zeros(k)

    # Exact 0/1 DP over weight for the full pool: best[wt] = max value with weight <= wt
    def best_fill(mask):
        best = np.full(rem + 1, 0.0)
        for j in range(k):
            if not mask[j]:
                continue
            wi = int(w[j])
            if wi > rem:
                continue
            cand = best[:rem + 1 - wi] + v[j]
            np.maximum(best[wi:], cand, out=best[wi:])
        return np.maximum.accumulate(best)

    full = best_fill(np.ones(k, dtype=bool))
    V_full = full[rem]
    if V_full <= 0:
        return np.zeros(k)

    out = np.empty(k)
    for i in range(k):
        mask = np.ones(k, dtype=bool)
        mask[i] = False
        out[i] = V_full - best_fill(mask)[rem]
    # marginal loss relative to full pool value; bigger loss = more essential item
    return np.clip(out / V_full, 0.0, 1.0) * 2.0 - 1.0
